INSERT INTO `internships` VALUES
(1,'Web Development Internship','web-development-internship','<h2>Web Development Internship</h2>\r\n\r\n<p>Kickstart your career in web development with our hands-on internship program designed for aspiring developers who want real-world experience.</p>\r\n\r\n<h3>About the Internship</h3>\r\n\r\n<p>Our <strong>Web Development Internship</strong> is a practical, project-based program where interns work on live websites and web applications. You&rsquo;ll learn industry-standard tools, coding practices, and workflows while being guided by experienced developers.</p>\r\n\r\n<p>This internship is ideal for students or freshers who want to build strong technical skills and a solid portfolio.</p>\r\n\r\n<hr />\r\n<h3>What You Will Learn</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>HTML5, CSS3, JavaScript (Core concepts)</p>\r\n	</li>\r\n	<li>\r\n	<p>Responsive Web Design &amp; Cross-Browser Compatibility</p>\r\n	</li>\r\n	<li>\r\n	<p>PHP / Core PHP Fundamentals</p>\r\n	</li>\r\n	<li>\r\n	<p>MySQL Database Design &amp; CRUD Operations</p>\r\n	</li>\r\n	<li>\r\n	<p>MVC Architecture Basics</p>\r\n	</li>\r\n	<li>\r\n	<p>Git &amp; Version Control</p>\r\n	</li>\r\n	<li>\r\n	<p>Debugging &amp; Performance Optimization</p>\r\n	</li>\r\n	<li>\r\n	<p>Basics of Web Security &amp; Best Practices</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h3>Roles &amp; Responsibilities</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Develop and maintain website features</p>\r\n	</li>\r\n	<li>\r\n	<p>Convert UI designs into functional web pages</p>\r\n	</li>\r\n	<li>\r\n	<p>Write clean, reusable, and optimized code</p>\r\n	</li>\r\n	<li>\r\n	<p>Integrate APIs and databases</p>\r\n	</li>\r\n	<li>\r\n	<p>Fix bugs and improve application performance</p>\r\n	</li>\r\n	<li>\r\n	<p>Collaborate with the development team on live projects</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h3>Who Can Apply</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Students pursuing <strong>BCA, MCA, B.Tech, M.Tech, or Diploma</strong></p>\r\n	</li>\r\n	<li>\r\n	<p>Freshers passionate about web development</p>\r\n	</li>\r\n	<li>\r\n	<p>Basic knowledge of HTML, CSS, or PHP is a plus</p>\r\n	</li>\r\n	<li>\r\n	<p>Strong willingness to learn and explore new technologies</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h3>Internship Details</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Duration:</strong> 1 / 3 / 6 Months</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Mode:</strong> Remote / On-site / Hybrid</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Working Hours:</strong> Flexible</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Stipend:</strong> Performance-based (if applicable)</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h3>What You&rsquo;ll Get</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Internship Completion Certificate</p>\r\n	</li>\r\n	<li>\r\n	<p>Live Project Experience</p>\r\n	</li>\r\n	<li>\r\n	<p>Letter of Recommendation (Top Performers)</p>\r\n	</li>\r\n	<li>\r\n	<p>Portfolio-worthy Projects</p>\r\n	</li>\r\n	<li>\r\n	<p>Mentorship &amp; Career Guidance</p>\r\n	</li>\r\n	<li>\r\n	<p>Opportunity for Full-Time Role (Based on Performance)</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h3>Why Join Us?</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Work on real client projects</p>\r\n	</li>\r\n	<li>\r\n	<p>Learn from industry professionals</p>\r\n	</li>\r\n	<li>\r\n	<p>Gain practical experience beyond theory</p>\r\n	</li>\r\n	<li>\r\n	<p>Build confidence for jobs &amp; freelancing</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h3>How to Apply</h3>\r\n\r\n<p>Submit your details and portfolio (if available).<br />\r\nShortlisted candidates will be contacted for a quick interview.</p>\r\n\r\n<p>? <strong>Apply Now &amp; Start Your Web Development Journey!</strong></p>\r\n','{\"amount\":\"1500\",\"description\":\"\"}',30,'Days','assets/uploads/internships/internship_1770832150.png','','','',1,'2026-01-27 18:23:15','2026-04-11 08:32:59'),
(2,'Digital Marketing Internship','digital-marketing-internship','<p>MG Education &amp; Social Development Organisation offers a <strong>Digital Marketing Internship</strong> designed to provide practical knowledge of online marketing strategies and tools. This internship focuses on real-world digital marketing practices, helping interns learn how to build brand presence, generate leads, and grow businesses through digital channels.</p>\r\n\r\n<hr />\r\n<h2>ðŸŽ¯ Internship Objectives</h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p>To understand the fundamentals of digital marketing</p>\r\n	</li>\r\n	<li>\r\n	<p>To develop practical marketing and analytical skills</p>\r\n	</li>\r\n	<li>\r\n	<p>To learn how businesses grow through online platforms</p>\r\n	</li>\r\n	<li>\r\n	<p>To gain hands-on experience with live digital marketing campaigns</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h2>ðŸ“š Internship Curriculum</h2>\r\n\r\n<h3>ðŸ”¹ Module 1: Introduction to Digital Marketing</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>What is Digital Marketing?</p>\r\n	</li>\r\n	<li>\r\n	<p>Traditional vs Digital Marketing</p>\r\n	</li>\r\n	<li>\r\n	<p>Digital Marketing Ecosystem</p>\r\n	</li>\r\n	<li>\r\n	<p>Understanding Online Consumer Behavior</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 2: Website &amp; Marketing Fundamentals</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Basics of Websites &amp; Landing Pages</p>\r\n	</li>\r\n	<li>\r\n	<p>Introduction to SEO-Friendly Websites</p>\r\n	</li>\r\n	<li>\r\n	<p>Content Marketing Basics</p>\r\n	</li>\r\n	<li>\r\n	<p>Understanding Customer Journey</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 3: Search Engine Optimization (SEO)</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>On-Page SEO Techniques</p>\r\n	</li>\r\n	<li>\r\n	<p>Off-Page SEO Strategies</p>\r\n	</li>\r\n	<li>\r\n	<p>Keyword Research</p>\r\n	</li>\r\n	<li>\r\n	<p>Technical SEO Basics</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 4: Social Media Marketing (SMM)</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Social Media Platforms Overview</p>\r\n	</li>\r\n	<li>\r\n	<p>Creating &amp; Managing Social Media Pages</p>\r\n	</li>\r\n	<li>\r\n	<p>Content Planning &amp; Scheduling</p>\r\n	</li>\r\n	<li>\r\n	<p>Growing Organic Reach &amp; Engagement</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 5: Paid Advertising (PPC)</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Introduction to Google Ads</p>\r\n	</li>\r\n	<li>\r\n	<p>Social Media Ads (Meta, Instagram)</p>\r\n	</li>\r\n	<li>\r\n	<p>Campaign Creation &amp; Optimization</p>\r\n	</li>\r\n	<li>\r\n	<p>Budgeting &amp; Performance Tracking</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 6: Email &amp; Affiliate Marketing</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Email Marketing Tools &amp; Strategies</p>\r\n	</li>\r\n	<li>\r\n	<p>Lead Generation &amp; Funnels</p>\r\n	</li>\r\n	<li>\r\n	<p>Affiliate Marketing Basics</p>\r\n	</li>\r\n	<li>\r\n	<p>Conversion Optimization</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 7: Analytics &amp; Performance Tracking</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Google Analytics Basics</p>\r\n	</li>\r\n	<li>\r\n	<p>Campaign Performance Analysis</p>\r\n	</li>\r\n	<li>\r\n	<p>Understanding KPIs &amp; Metrics</p>\r\n	</li>\r\n	<li>\r\n	<p>Reporting &amp; Optimization</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 8: Live Digital Marketing Project</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Real-World Marketing Campaign</p>\r\n	</li>\r\n	<li>\r\n	<p>Strategy Planning &amp; Execution</p>\r\n	</li>\r\n	<li>\r\n	<p>Performance Monitoring &amp; Optimization</p>\r\n	</li>\r\n	<li>\r\n	<p>Final Project Presentation</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h2>ðŸ› ï¸ What You Will Learn</h2>\r\n\r\n<p>âœ” Digital Marketing Fundamentals<br />\r\nâœ” SEO &amp; Keyword Research<br />\r\nâœ” Social Media Marketing Strategies<br />\r\nâœ” Paid Advertising Basics<br />\r\nâœ” Email &amp; Content Marketing<br />\r\nâœ” Campaign Analysis &amp; Reporting<br />\r\nâœ” Real-World Marketing Execution</p>\r\n\r\n<hr />\r\n<h2>ðŸŽ What You Will Get</h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p>ðŸ“œ <strong>Internship Completion Certificate</strong></p>\r\n	</li>\r\n	<li>\r\n	<p>ðŸ† <strong>Project Completion Certificate</strong></p>\r\n	</li>\r\n	<li>\r\n	<p>ðŸ“Š Hands-on Marketing Experience</p>\r\n	</li>\r\n	<li>\r\n	<p>ðŸ’¼ Career Guidance &amp; Mentorship</p>\r\n	</li>\r\n	<li>\r\n	<p>ðŸ“ Live Campaigns for Portfolio</p>\r\n	</li>\r\n	<li>\r\n	<p>ðŸš€ Better Career Opportunities in Marketing &amp; Business Domains</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h2>ðŸ‘©&zwj;ðŸŽ“ Who Can Apply</h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Students from Any Stream</p>\r\n	</li>\r\n	<li>\r\n	<p>Beginners interested in Digital Marketing</p>\r\n	</li>\r\n	<li>\r\n	<p>Aspiring Digital Marketers</p>\r\n	</li>\r\n	<li>\r\n	<p>Entrepreneurs &amp; Freelancers</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h2>â³ Internship Duration</h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Flexible Duration (4 Weeks / 6 Weeks / 8 Weeks)</p>\r\n	</li>\r\n	<li>\r\n	<p>Mode: Online / Offline (as per availability)</p>\r\n	</li>\r\n</ul>\r\n','{\"amount\":\"1500\",\"description\":\"\"}',3,'Months','assets/uploads/internships/internship_1770458333.jpg','Digital Marketing Internship 2026 | SEO & Social Media','Digital Marketing Internship 2026 with live projects in SEO, social media marketing, Google Ads and certification.','digital marketing internship, seo internship, social media internship, online marketing course',1,'2026-02-07 09:58:53','2026-02-12 07:27:30'),
(3,'Data Analytics Internship','data-analytics-internship','<p>MG Education &amp; Social Development Organisation offers a <strong>Data Analytics Internship</strong> aimed at developing strong data analysis and interpretation skills. This internship provides hands-on experience in working with real datasets, extracting meaningful insights, and supporting data-driven decision-making using modern analytics tools and techniques.</p>\r\n\r\n<hr />\r\n<h2>ðŸŽ¯ Internship Objectives</h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p>To build strong analytical and problem-solving skills</p>\r\n	</li>\r\n	<li>\r\n	<p>To understand the complete data analytics lifecycle</p>\r\n	</li>\r\n	<li>\r\n	<p>To gain practical experience with real-world datasets</p>\r\n	</li>\r\n	<li>\r\n	<p>To prepare interns for careers in data analytics and related fields</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h2>ðŸ“š Internship Curriculum</h2>\r\n\r\n<h3>ðŸ”¹ Module 1: Introduction to Data Analytics</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>What is Data Analytics?</p>\r\n	</li>\r\n	<li>\r\n	<p>Role of Data Analyst in Organizations</p>\r\n	</li>\r\n	<li>\r\n	<p>Types of Analytics (Descriptive, Diagnostic, Predictive)</p>\r\n	</li>\r\n	<li>\r\n	<p>Data Analytics Workflow</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 2: Data Fundamentals</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Data Types &amp; Data Sources</p>\r\n	</li>\r\n	<li>\r\n	<p>Data Collection Methods</p>\r\n	</li>\r\n	<li>\r\n	<p>Data Cleaning &amp; Data Preprocessing</p>\r\n	</li>\r\n	<li>\r\n	<p>Handling Missing &amp; Duplicate Data</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 3: Excel for Data Analysis</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Data Sorting &amp; Filtering</p>\r\n	</li>\r\n	<li>\r\n	<p>Formulas &amp; Functions</p>\r\n	</li>\r\n	<li>\r\n	<p>Pivot Tables &amp; Charts</p>\r\n	</li>\r\n	<li>\r\n	<p>Data Analysis Using Excel</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 4: SQL for Data Analytics</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Introduction to Databases</p>\r\n	</li>\r\n	<li>\r\n	<p>Writing SQL Queries</p>\r\n	</li>\r\n	<li>\r\n	<p>Data Filtering, Joins &amp; Aggregations</p>\r\n	</li>\r\n	<li>\r\n	<p>Extracting Insights Using SQL</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 5: Data Visualization</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Data Visualization Principles</p>\r\n	</li>\r\n	<li>\r\n	<p>Creating Charts &amp; Dashboards</p>\r\n	</li>\r\n	<li>\r\n	<p>Introduction to Power BI / Tableau</p>\r\n	</li>\r\n	<li>\r\n	<p>Visual Storytelling with Data</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 6: Python Basics for Data Analysis</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Introduction to Python for Analytics</p>\r\n	</li>\r\n	<li>\r\n	<p>Working with Pandas &amp; NumPy</p>\r\n	</li>\r\n	<li>\r\n	<p>Basic Data Analysis Using Python</p>\r\n	</li>\r\n	<li>\r\n	<p>Data Visualization Basics (Matplotlib overview)</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 7: Real-World Data Analytics Project</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Working with Real Datasets</p>\r\n	</li>\r\n	<li>\r\n	<p>Data Cleaning &rarr; Analysis &rarr; Visualization</p>\r\n	</li>\r\n	<li>\r\n	<p>Insight Generation &amp; Reporting</p>\r\n	</li>\r\n	<li>\r\n	<p>Final Project Presentation &amp; Evaluation</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h2>ðŸ› ï¸ What You Will Learn</h2>\r\n\r\n<p>âœ” Data Cleaning &amp; Preprocessing<br />\r\nâœ” Excel &amp; SQL for Analytics<br />\r\nâœ” Data Visualization &amp; Dashboards<br />\r\nâœ” Python Basics for Data Analysis<br />\r\nâœ” Analytical &amp; Critical Thinking<br />\r\nâœ” Business &amp; Data Insight Generation<br />\r\nâœ” Project-Based Analytics Experience</p>\r\n\r\n<hr />\r\n<h2>ðŸŽ What You Will Get</h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p>ðŸ“œ <strong>Internship Completion Certificate</strong></p>\r\n	</li>\r\n	<li>\r\n	<p>ðŸ† <strong>Project Completion Certificate</strong></p>\r\n	</li>\r\n	<li>\r\n	<p>ðŸ“Š Hands-on Experience with Real Data</p>\r\n	</li>\r\n	<li>\r\n	<p>ðŸ’¼ Career Guidance &amp; Mentorship</p>\r\n	</li>\r\n	<li>\r\n	<p>ðŸ“ Data Analytics Projects for Portfolio</p>\r\n	</li>\r\n	<li>\r\n	<p>ðŸš€ Improved Career Opportunities in Analytics &amp; Data Domains</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h2>ðŸ‘©&zwj;ðŸŽ“ Who Can Apply</h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Students from Any Stream</p>\r\n	</li>\r\n	<li>\r\n	<p>Beginners interested in Data Analytics</p>\r\n	</li>\r\n	<li>\r\n	<p>Aspiring Data Analysts</p>\r\n	</li>\r\n	<li>\r\n	<p>Anyone looking to build a data-driven career</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h2>â³ Internship Duration</h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Flexible Duration (4 Weeks / 6 Weeks / 8 Weeks)</p>\r\n	</li>\r\n	<li>\r\n	<p>Mode: Online / Offline (as per availability)</p>\r\n	</li>\r\n</ul>\r\n','{\"amount\":\"1500\",\"description\":\"\"}',3,'Months','assets/uploads/internships/internship_1770458565.jpg','Data Analytics Internship 2026 | Excel SQL Python','Apply for Data Analytics Internship 2026 and gain practical experience in Excel, SQL, Python and data visualization.','data analytics internship, excel internship, sql internship, python data analysis',1,'2026-02-07 10:02:45','2026-02-12 07:26:10'),
(4,'Python Programming Internship','python-programming-internship','<p>MG Education &amp; Social Development Organisation offers a <strong>Python Programming Internship</strong> designed to help students and beginners build strong programming foundations and practical coding skills. This internship focuses on real-world problem solving, hands-on coding, and project-based learning using Python&mdash;one of the most versatile and in-demand programming languages today.</p>\r\n\r\n<hr />\r\n<h2>ðŸŽ¯ Internship Objectives</h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p>To develop strong programming and logical thinking skills</p>\r\n	</li>\r\n	<li>\r\n	<p>To understand Python fundamentals and advanced concepts</p>\r\n	</li>\r\n	<li>\r\n	<p>To gain hands-on experience through real-world coding projects</p>\r\n	</li>\r\n	<li>\r\n	<p>To prepare interns for careers in software development, automation, and data-related fields</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h2>ðŸ“š Internship Curriculum</h2>\r\n\r\n<h3>ðŸ”¹ Module 1: Introduction to Python</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Introduction to Programming &amp; Python</p>\r\n	</li>\r\n	<li>\r\n	<p>Installing &amp; Setting Up Python</p>\r\n	</li>\r\n	<li>\r\n	<p>Python Syntax &amp; Structure</p>\r\n	</li>\r\n	<li>\r\n	<p>Variables, Data Types &amp; Operators</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 2: Core Python Concepts</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Conditional Statements (if-else)</p>\r\n	</li>\r\n	<li>\r\n	<p>Loops (for, while)</p>\r\n	</li>\r\n	<li>\r\n	<p>Functions &amp; Modules</p>\r\n	</li>\r\n	<li>\r\n	<p>Input/Output Handling</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 3: Data Structures in Python</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Lists, Tuples &amp; Sets</p>\r\n	</li>\r\n	<li>\r\n	<p>Dictionaries</p>\r\n	</li>\r\n	<li>\r\n	<p>String Manipulation</p>\r\n	</li>\r\n	<li>\r\n	<p>Practical Use Cases of Data Structures</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 4: Object-Oriented Programming (OOP)</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Classes &amp; Objects</p>\r\n	</li>\r\n	<li>\r\n	<p>Inheritance, Polymorphism &amp; Encapsulation</p>\r\n	</li>\r\n	<li>\r\n	<p>Constructors &amp; Methods</p>\r\n	</li>\r\n	<li>\r\n	<p>Real-World OOP Examples</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 5: File Handling &amp; Exception Handling</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Reading &amp; Writing Files</p>\r\n	</li>\r\n	<li>\r\n	<p>Working with CSV &amp; Text Files</p>\r\n	</li>\r\n	<li>\r\n	<p>Exception Handling (try-except)</p>\r\n	</li>\r\n	<li>\r\n	<p>Error Debugging Techniques</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 6: Libraries &amp; Practical Applications</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Working with Python Libraries</p>\r\n	</li>\r\n	<li>\r\n	<p>Introduction to Automation</p>\r\n	</li>\r\n	<li>\r\n	<p>Basics of Web Scraping</p>\r\n	</li>\r\n	<li>\r\n	<p>Overview of Data Analysis &amp; APIs</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3>ðŸ”¹ Module 7: Live Python Project</h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Real-World Python Project</p>\r\n	</li>\r\n	<li>\r\n	<p>Problem Analysis &amp; Solution Design</p>\r\n	</li>\r\n	<li>\r\n	<p>Coding, Testing &amp; Debugging</p>\r\n	</li>\r\n	<li>\r\n	<p>Final Project Submission &amp; Review</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr />\r\n<h2>ðŸ› ï¸ What You Will Learn</h2>\r\n\r\n<p>âœ” Python Programming Fundamentals<br />\r\nâœ” Problem-Solving &amp; Logical Thinking<br />\r\nâœ” Object-Oriented Programming<br />\r\nâœ” File &amp; Data Handling<br />\r\nâœ” Working with Python Libraries<br />\r\nâœ” Debugging &amp; Error Handling<br />\r\nâœ” Project-Based Learning</p>\r\n\r\n<hr />\r\n<h2>ðŸŽ What You Will Get</h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p>ðŸ“œ <strong>Internship Completion Certificate</strong></p>\r\n	</li>\r\n	<li>\r\n	<p>ðŸ† <strong>Project Completion Certificate</strong></p>\r\n	</li>\r\n	<li>\r\n	<p>ðŸ§  Strong Programming Foundation</p>\r\n	</li>\r\n	<li>\r\n	<p>ðŸ’¼ Career Guidance &amp; Mentorship</p>\r\n	</li>\r\n	<li>\r\n	<p>ðŸ“‚ Real Projects for Coding Portf